std::priority_queue<std::pair<double, int>, std::vector<std::pair<double, int>>, std::greater<std::pair<double, int>>> open_set;
std::vector<double> g_score(graph.nodes.size(), std::numeric_limits<double>::infinity());
std::vector<double> f_score(graph.nodes.size(), std::numeric_limits<double>::infinity());
std::vector<int> came_from(graph.nodes.size(), -1);
std::vector<bool> closed_set(graph.nodes.size(), false);

g_score[start_idx] = 0.0;
f_score[start_idx] = graph.nodes[start_idx].heuristic_to(graph.nodes[end_idx]);

open_set.push({f_score[start_idx], start_idx});

while (!open_set.empty()) {
    int current = open_set.top().second;
    open_set.pop();

    if (closed_set[current]) continue;
    closed_set[current] = true;

    if (current == end_idx) {
        std::vector<Node> path;
        for (int curr = end_idx; curr != -1; curr = came_from[curr]) {
            path.push_back(graph.nodes[curr]);
        }
        std::reverse(path.begin(), path.end());
        return path;
    }

    for (const auto& edge : graph.nodes[current].neighbors) {
        int neighbor_idx = edge.first;
        if (closed_set[neighbor_idx]) continue;

        double tentative_g_score = g_score[current] + edge.second;
        if (tentative_g_score < g_score[neighbor_idx]) {
            came_from[neighbor_idx] = current;
            g_score[neighbor_idx] = tentative_g_score;
            f_score[neighbor_idx] = g_score[neighbor_idx] + graph.nodes[neighbor_idx].heuristic_to(graph.nodes[end_idx]);
            open_set.push({f_score[neighbor_idx], neighbor_idx});
        }
    }
}

return {}; // No path found
